-- The real logos for the firm's two partners on the home page, in place of
-- Nectarray's initials and the cartoon cookie: each the partner's own logo,
-- trimmed and centred on a 400 x 400 px transparent PNG. Matched by name, so
-- a database without these partners is left as it is.

UPDATE "Partner"
SET "logoData" = decode('', 'hex'),
    "logoType" = 'image/png', "logoUpdatedAt" = CURRENT_TIMESTAMP, "updatedAt" = CURRENT_TIMESTAMP
WHERE "name" ILIKE 'nectarray';

UPDATE "Partner"
SET "logoData" = decode('', 'hex'),
    "logoType" = 'image/png', "logoUpdatedAt" = CURRENT_TIMESTAMP, "updatedAt" = CURRENT_TIMESTAMP
WHERE "name" ILIKE '%dough%cookie%';
